-- Main Hyprland Lua config.

local hypr_dir = os.getenv("HOME") .. "/.config/hypr"

package.path = hypr_dir .. "/?.lua;" .. hypr_dir .. "/?/init.lua;" .. package.path

require("lua.env")
require("lua.general")
require("lua.rules")
require("lua.keybinds")
require("lua.execs")

-- Window blur and wobble chosen in Quickshell (Settings → Effects). The file
-- is generated by Quickshell; a missing one never breaks the main config.
pcall(require, "lua.quickshell_effects")

-- Mouse speed and acceleration chosen in Quickshell (Settings → Mouse), so
-- they are not reset to defaults when Hyprland reloads.
pcall(require, "lua.quickshell_input")

-- Monitor mode, scale, position and colour chosen in Quickshell
-- (Settings → Monitors), matched by EDID so they survive port changes.
pcall(require, "lua.quickshell_monitors")

-- Optional machine-specific overrides (monitors, rules for custom Hyprland
-- builds) live in lua/local.lua, which is not part of the shared config.
-- A missing or failing local.lua never breaks the main config.
pcall(require, "lua.local")
